DO $$ DECLARE t text; pol record; BEGIN FOREACH t IN ARRAY ARRAY['teams','groups','athletes','meets','events','results','splits','time_standards','import_logs','clubs','club_members','club_documents'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN owner_id uuid DEFAULT auth.uid()',t); EXECUTE format('UPDATE public.%I SET owner_id=(SELECT user_id FROM public.app_owner WHERE singleton) WHERE owner_id IS NULL',t); EXECUTE format('CREATE INDEX ON public.%I(owner_id)',t); FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',pol.policyname,t); END LOOP; EXECUTE format('CREATE POLICY "private account records" ON public.%I FOR ALL TO authenticated USING (owner_id=auth.uid() AND public.has_role(auth.uid(),''admin'')) WITH CHECK (owner_id=auth.uid() AND public.has_role(auth.uid(),''admin''))',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.guard_private_row() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE row_data jsonb := to_jsonb(NEW); parent_id text; parent_owner uuid; parent_table text; field text; BEGIN IF TG_OP='UPDATE' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'No se puede cambiar el propietario'; END IF; IF NEW.owner_id IS NULL OR NEW.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Propietario inválido'; END IF; FOR field,parent_table IN SELECT * FROM (VALUES ('team_id','teams'),('group_id','groups'),('club_id','clubs'),('document_id','club_documents'),('athlete_id','athletes'),('meet_id','meets'),('event_id','events'),('result_id','results')) AS refs(f,t) LOOP parent_id := row_data->>field; IF parent_id IS NOT NULL THEN EXECUTE format('SELECT owner_id FROM public.%I WHERE id=$1',parent_table) INTO parent_owner USING parent_id::uuid; IF parent_owner IS DISTINCT FROM NEW.owner_id THEN RAISE EXCEPTION 'El registro relacionado no pertenece a tu cuenta'; END IF; END IF; END LOOP; IF TG_TABLE_NAME='club_documents' THEN IF split_part(row_data->>'storage_path','/',1) IS DISTINCT FROM row_data->>'club_id' THEN RAISE EXCEPTION 'Ruta de documento inválida'; END IF; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.guard_private_row() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['teams','groups','athletes','meets','events','results','splits','time_standards','import_logs','clubs','club_members','club_documents'] LOOP EXECUTE format('CREATE TRIGGER guard_private_row BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_private_row()',t); END LOOP; END $$;
ALTER TABLE public.teams DROP CONSTRAINT teams_code_key;
ALTER TABLE public.teams ADD CONSTRAINT teams_owner_code_key UNIQUE(owner_id,code);
ALTER TABLE public.groups DROP CONSTRAINT groups_code_key;
ALTER TABLE public.groups ADD CONSTRAINT groups_owner_code_key UNIQUE(owner_id,code);
ALTER TABLE public.athletes DROP CONSTRAINT athletes_tm_athlete_id_key;
ALTER TABLE public.athletes ADD CONSTRAINT athletes_owner_tm_key UNIQUE(owner_id,tm_athlete_id);
DROP POLICY "admins club files" ON storage.objects;
CREATE POLICY "private club files" ON storage.objects FOR ALL TO authenticated USING(bucket_id='club-documents' AND public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.clubs c WHERE c.owner_id=auth.uid() AND c.id::text=split_part(name,'/',1))) WITH CHECK(bucket_id='club-documents' AND public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.clubs c WHERE c.owner_id=auth.uid() AND c.id::text=split_part(name,'/',1)));